def main():
 java=Path(os.environ.get('JAVA_HOME','/nonexistent'))/'bin'
 with tempfile.TemporaryDirectory(prefix='pi-file-native-') as tmp:
  base=Path(tmp)
  for name,source in sources.items():
   p=base/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(source)
  production=[root/'android/src/dev/piconsole'/name for name in ['FileTransfer.java','TransferEngine.java','TransferBinding.java']]
  subprocess.run([str(java/'javac') if (java/'javac').exists() else 'javac','--release','8','-d',tmp,*map(str,production),*map(str,base.rglob('*.java'))],check=True)
  subprocess.run([str(java/'java') if (java/'java').exists() else 'java','-cp',tmp,'dev.piconsole.FileNativeTest'],check=True)

if __name__=='__main__':main()
